import { readFile } from "node:fs/promises";

export async function normalizeFixture(path) {
  const fixture = JSON.parse(await readFile(path, "utf8"));
  let expectedSeq = 1;
  let openRun = null;
  const attempts = new Map();
  const events = fixture.items.map((item) => {
    if (item.seq !== expectedSeq++) {
      throw new Error(`non-contiguous fixture seq at ${item.id}`);
    }
    if (item.type === "operation_started") {
      if (openRun !== null) throw new Error("a lane may have only one open run");
      openRun = item.runId;
    } else if (item.type === "step_attempt") {
      if (item.runId !== openRun) throw new Error("attempt references a non-open run");
      const key = [REDACTED_CREDENTIAL]
      const expectedAttempt = (attempts.get(key) ?? 0) + 1;
      if (item.data.attempt !== expectedAttempt) throw new Error("attempt numbers must be contiguous");
      attempts.set(key, expectedAttempt);
    } else if (item.type === "operation_finished") {
      if (item.runId !== openRun) throw new Error("finish references a non-open run");
      openRun = null;
    }
    return {
      seq: item.seq,
      kind: item.kind,
      type: item.type,
      id: item.id,
      parentId: item.parentId ?? null,
      runId: item.runId ?? null,
      timestamp: item.timestamp,
      data: sortObject(item.data),
    };
  });
  if (openRun !== null) throw new Error(`run ${openRun} remains open`);
  return { schemaVersion: "canonical-event-v1", fixtureId: fixture.fixtureId, events };
}

function sortObject(value) {
  if (Array.isArray(value)) return value.map(sortObject);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, sortObject(value[key])]));
  }
  return value;
}
